CREATE TABLE `dev_raw.recruitee_postings` (
    id INT64 NOT NULL OPTIONS(description="Recruitee's own posting id ('id'), an integer. Unique per row: this is the merge key. Recruitee also sends 'guid' (short string, e.g. 'cov6o') and 'slug' (derived from the title, so it changes when the title is edited); both stay in 'raw'."),
    title STRING OPTIONS(description="Job title in the chosen language (see 'language'), from 'translations.<language>.title'. Not cleaned."),
    language STRING OPTIONS(description="Language code of the text stored in title, content, requirements and highlight, e.g. 'en', 'pt', 'de'. Chosen by the loader, not sent by the source: English if the posting has it, else Portuguese, else the first translation available. Recruitee postings can carry several translations (e.g. 'en' and 'it'); the others are kept only in 'raw'. Nothing in the payload says which language the top-level fields are in, which is why the loader reads from 'translations' and records its choice here."),
    url STRING OPTIONS(description="Public URL of the posting, from 'careers_url'. Often on the company's own domain rather than recruitee.com. The apply link ('careers_apply_url') is this URL plus '/c/new' and is not stored."),
    location STRING OPTIONS(description="Location display string as published, from 'location', e.g. 'Remote job' or a city. Not normalised. Structured parts ('city', 'state_code', 'postal_code') and the 'locations' array stay in 'raw'."),
    remote BOOL OPTIONS(description="Whether the posting is marked remote, from 'remote'. One of three independent booleans (with hybrid and on_site); all three are kept so the canonical four-value workplace type can be derived without guessing - 'remote = false' alone cannot tell hybrid from on-site."),
    hybrid BOOL OPTIONS(description="Whether the posting is marked hybrid, from 'hybrid'. See 'remote'."),
    on_site BOOL OPTIONS(description="Whether the posting is marked on-site, from 'on_site'. See 'remote'."),
    country_code STRING OPTIONS(description="Country as an ISO-3166 alpha-2 code, from 'country_code', e.g. 'US'. The only source so far whose country needs no mapping. The display name ('country', e.g. 'United States') stays in 'raw'."),
    department STRING OPTIONS(description="Department as published, from 'department'. Often null: many boards do not use it."),
    employment_type STRING OPTIONS(description="Employment type as published, from 'employment_type_code', e.g. 'freelance', 'fulltime'. Recruitee's own codes, NOT normalised despite the neutral name: Lever says 'Full-Time', Ashby 'FullTime'. Mapping to one vocabulary happens downstream."),
    content STRING OPTIONS(description="Main job description in the chosen language, from 'translations.<language>.description'. HTML, stored unparsed. Recruitee splits its text into three sections - this one, 'requirements' and 'highlight' - each kept as its own column, as lever_postings keeps 'additional'. Assembling the full text is a downstream decision."),
    requirements STRING OPTIONS(description="Requirements section in the chosen language, from 'translations.<language>.requirements'. HTML, stored unparsed. A real share of the text (329 of ~2,200 characters in the survey sample), so it is a column, not left in 'raw'."),
    highlight STRING OPTIONS(description="Short highlight/teaser section in the chosen language, from 'translations.<language>.highlight'. HTML, stored unparsed."),
    salary_min NUMERIC OPTIONS(description="Lower bound of the advertised salary, from 'salary.min'. The 'salary' object is present in every posting but its values are usually all null: the field existing does not mean the data does - read the fill rate. NUMERIC: money is never stored as a float."),
    salary_max NUMERIC OPTIONS(description="Upper bound of the advertised salary, from 'salary.max'."),
    salary_currency STRING OPTIONS(description="Currency of the advertised salary, from 'salary.currency'."),
    salary_period STRING OPTIONS(description="Period the salary refers to, from 'salary.period'. Named 'period' after Recruitee's field; lever_postings and ashby_postings call the same idea 'salary_interval', with different values. Mapping happens downstream."),
    published_at TIMESTAMP OPTIONS(description="When the posting was published, as reported by the source ('published_at', e.g. '2026-09-25 10:47:06 UTC' - not ISO-8601, but BigQuery parses it as-is, so the loader passes it through). A source timestamp, not a pipeline one."),
    updated_at TIMESTAMP OPTIONS(description="When the source last changed the posting ('updated_at', same format as published_at). With Greenhouse, one of only two sources that say when a posting changed; for Lever and Ashby, last_seen_at is the only freshness signal."),
    raw STRING NOT NULL OPTIONS(description="The complete original API object for this posting, as JSON text. Kept so anything dropped or flattened above - the other translations, 'guid', 'slug', structured location parts, 'country', 'careers_apply_url', 'status' - can be recovered without re-fetching. Also contains 'mailbox_email', an operational role-based address published by the source; deliberately not a column."),
    company_slug STRING OPTIONS(description="The board this posting was fetched from: the company's identifier on its ATS, equal to external_id in dev_raw.companies (join on ats + external_id), e.g. 'gitlab'. Not sent by the source - stamped by the loader from the landed file's path (<source>/ingest_date=<date>/<slug>/<time>), in one place for every ATS. NULL for a posting last seen before 2026-10-06, when the column was added."),
    first_seen_at TIMESTAMP NOT NULL OPTIONS(description="When this job was FIRST seen in a landed file (the GCS object's creation time), not when the loader ran. Only ever moves earlier: re-loading an older day corrects it."),
    last_seen_at TIMESTAMP NOT NULL OPTIONS(description="When this job was MOST RECENTLY seen in a landed file (the GCS object's creation time), not when the loader ran. Only ever moves later: older data cannot overwrite a newer row."),
    PRIMARY KEY (id) NOT ENFORCED
)
OPTIONS(description="One row per Recruitee job posting, holding its current state (not one row per ingestion). Raw layer: values are as published by the source, flattened but not cleaned or normalised, and kept under Recruitee's own vocabulary where it differs from other sources. Text columns hold ONE language per posting, chosen by the loader and recorded in 'language'. Loaded daily by the recruitee_ingestion DAG, which replaces dev_raw.recruitee_postings_incoming and MERGEs it here on id, newest landed file wins. Full history of every API response is kept as files in GCS, not in this table.");
